package com.fuelflex.platform.reception.controller; import java.util.*; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.fuelflex.platform.reception.dto.ReceptionDtos.*; import com.fuelflex.platform.reception.service.ReceptionService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class ReceptionController { private final ReceptionService service; @GetMapping("/manager/receptions") @PreAuthorize("hasAuthority('reception:view')") public Page<Response> managerList(Pageable p){return service.managerList(p);} @GetMapping("/manager/receptions/{id}") @PreAuthorize("hasAuthority('reception:view')") public Response managerGet(@PathVariable UUID id){return service.managerGet(id);} @PostMapping("/manager/receptions") @PreAuthorize("hasAuthority('reception:create')") public Response create(@Valid @RequestBody ReceptionCreateRequest r){return service.create(r);} @PutMapping("/manager/receptions/{id}") @PreAuthorize("hasAuthority('reception:update')") public Response update(@PathVariable UUID id,@Valid @RequestBody ReceptionUpdateRequest r){return service.update(id,r);} @PostMapping("/manager/receptions/{id}/submit") @PreAuthorize("hasAuthority('reception:submit')") public Response submit(@PathVariable UUID id,@RequestBody(required=false) ReceptionSubmitRequest r){return service.submit(id,r);} @GetMapping("/manager/receptions/{id}/history") @PreAuthorize("hasAuthority('reception:view')") public List<HistoryResponse> managerHistory(@PathVariable UUID id){return service.managerHistory(id);} @GetMapping("/supervisor/receptions") @PreAuthorize("hasAuthority('reception:view')") public Page<Response> supervisorList(Pageable p){return service.supervisorList(p);} @GetMapping("/supervisor/receptions/{id}") @PreAuthorize("hasAuthority('reception:view')") public Response supervisorGet(@PathVariable UUID id){return service.supervisorGet(id);} @PostMapping("/supervisor/receptions/{id}/approve") @PreAuthorize("hasAuthority('reception:approve')") public Response approve(@PathVariable UUID id,@Valid @RequestBody SupervisorReceptionDecisionRequest r){return service.approve(id,r);} @PostMapping("/supervisor/receptions/{id}/return") @PreAuthorize("hasAuthority('reception:return')") public Response returnForCorrection(@PathVariable UUID id,@Valid @RequestBody SupervisorReceptionDecisionRequest r){return service.returnForCorrection(id,r);} @PostMapping("/supervisor/receptions/{id}/cancel") @PreAuthorize("hasAuthority('reception:cancel')") public Response cancel(@PathVariable UUID id,@Valid @RequestBody SupervisorReceptionDecisionRequest r){return service.cancel(id,r);} @GetMapping("/supervisor/receptions/{id}/history") @PreAuthorize("hasAuthority('reception:view')") public List<HistoryResponse> supervisorHistory(@PathVariable UUID id){return service.supervisorHistory(id);} }
